/// Decode one binary sub-table by the name ExifTool gives it, module first:
/// `Canon::ShotInfo`. Two modules can name a table the same thing.
#[must_use]
pub fn decode(
    table: &str,
    data: &[u8],
    make: &str,
    model: &str,
    bo: ByteOrder,
    file_type: &str,
    format: &str,
    dm: &mut State,
) -> Vec<Tag> {
    let file = FileInfo {
        make,
        model,
        bo,
        file_type,
        format,
    };
    binary_tables::decode(TABLES, table, data, &file, dm)
}

/// What every field below is unless it says otherwise.
const F: Field = Field::DEFAULT;

fn cond_0(data: &[u8], make: &str, model: &str, file_type: &str, format: &str, dm: &State) -> bool {
    let _ = (data, make, model, file_type, format, dm);
    (dm_get(dm, "ColorDataVersion").is_some_and(|v| v == 4.0)
        || dm_get(dm, "ColorDataVersion").is_some_and(|v| v == 5.0))
}
